#!/usr/bin/env bash
# Zeche installer — run this inside the docker LXC (10.10.10.3).
#   curl -sSL <url> -o install-zeche.sh && bash install-zeche.sh
# Idempotent: re-running rebuilds the image and leaves ./data untouched.
set -euo pipefail

DIR="${ZECHE_DIR:-/opt/zeche}"
HOSTNAME_PUBLIC="${ZECHE_HOST:-bill.kronask.cc}"

say() { printf '\033[38;5;179m==>\033[0m %s\n' "$*"; }
die() { printf '\033[31mxx\033[0m %s\n' "$*" >&2; exit 1; }

command -v docker >/dev/null || die "docker is not installed in this container"
docker compose version >/dev/null 2>&1 || die "the docker compose plugin is missing"

if [ -d "$DIR/data" ]; then
  say "Existing install found at $DIR — keeping data/, replacing the code"
  BACKUP="/tmp/zeche-db-$(date +%Y%m%d-%H%M%S).db"
  [ -f "$DIR/data/zeche.db" ] && cp "$DIR/data/zeche.db" "$BACKUP" && say "Database copied to $BACKUP"
  (cd "$DIR" && docker compose down 2>/dev/null || true)
  find "$DIR" -mindepth 1 -maxdepth 1 ! -name data -exec rm -rf {} +
fi

mkdir -p "$DIR"
say "Unpacking into $DIR"
base64 -d <<'PAYLOAD_B64' | tar xz -C "$DIR" --strip-components=1

PAYLOAD_B64

cd "$DIR"
mkdir -p data
[ -f .env ] || cp .env.example .env

sed -i "s|ZECHE_BASE_URL: .*|ZECHE_BASE_URL: https://$HOSTNAME_PUBLIC|" docker-compose.yml

say "Building the image (a few minutes: tesseract + the deu/eng language data)"
docker compose build

say "Starting zeche + libretranslate"
say "LibreTranslate downloads ~5 language models on first boot — this is the slow part"
docker compose up -d

printf '\n'
say "Waiting for the health check"
for i in $(seq 1 90); do
  if curl -fsS http://127.0.0.1:8080/healthz >/dev/null 2>&1; then
    printf '\n'
    say "Zeche is up on port 8080"
    echo
    curl -sS http://127.0.0.1:8080/api/config | sed 's/^/    /'
    echo
    echo
    echo "  Next, on the cloudflared LXC (10.10.10.x, the one serving kronask.cc):"
    echo
    echo "    1. Add to its config.yml, ABOVE the http_status:404 catch-all:"
    echo
    echo "         - hostname: $HOSTNAME_PUBLIC"
    echo "           service: http://$(hostname -I | awk '{print $1}'):8080"
    echo "           originRequest:"
    echo "             connectTimeout: 30s"
    echo
    echo "    2. cloudflared tunnel route dns <tunnel-name> $HOSTNAME_PUBLIC"
    echo "    3. systemctl restart cloudflared"
    echo
    echo "  Then open https://$HOSTNAME_PUBLIC and add it to your home screen."
    echo "  Logs: cd $DIR && docker compose logs -f zeche"
    exit 0
  fi
  printf '.'
  sleep 2
done

printf '\n'
die "No health check response after 3 minutes. Check: cd $DIR && docker compose logs zeche"
